def count_squares(lines):
    def is_square(x1, y1, x2, y2):
        # Check if the rectangle formed by (x1, y1) and (x2, y2) is a square
        return x2 - x1 == y2 - y1 and x1 != y1

    def find_corners(x1, y1, x2, y2):
        # Find all corners of the rectangle
        corners = []
        if x1 != x2:
            corners.append((x1, y1))
            corners.append((x1, y2))
        if y1 != y2:
            corners.append((x1, y1))
            corners.append((x2, y1))
        return corners

    def find_squares_in_line(line):
        # Find all squares in a single line
        squares = 0
        for i in range(len(line) - 1):
            for j in range(i + 1, len(line)):
                if line[i] == '+' and line[j] == '+':
                    # Find the corners of the rectangle formed by the two '+'
                    corners = find_corners(i, j, len(line) - 1, len(line) - 1)
                    # Check if all corners are '+' and form a square
                    if all(line[x] == '+' for x, y in corners):
                        squares += 1
        return squares

    total_squares = 0
    # Count squares in each line
    for line in lines:
        total_squares += find_squares_in_line(line)
    return total_squares
